test("browser channel rejects replay and route metadata changes", () => {
  const route = { tenantId: "tenant-1", routeId: "route-1", hostId: "host-1", deviceId: "device-1" }
  const clientSend = crypto.getRandomValues(new Uint8Array(32))
  const hostSend = crypto.getRandomValues(new Uint8Array(32))
  const client = new NoiseChannel(clientSend.slice(), hostSend.slice(), route)
  const host = new NoiseChannel(hostSend.slice(), clientSend.slice(), route)
  const frame = client.encrypt(new TextEncoder().encode("hcp"))
  expect(() => host.decrypt(frame)).toThrow()
  expect(() => host.decrypt(frame)).toThrow()
})

